import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.Cz0TtJv6.js";const u=JSON.parse('{"title":"CLI reference","description":"Every npm script that matters — scan, vet, run, status, halt, pause, release, force-close, dash — what each prints and when to use it.","frontmatter":{"title":"CLI reference","description":"Every npm script that matters — scan, vet, run, status, halt, pause, release, force-close, dash — what each prints and when to use it."},"headers":[],"relativePath":"cli.md","filePath":"cli.md","lastUpdated":1787232205000}'),n={name:"cli.md"};function i(r,e,d,h,l,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>All commands run from the repo root. Arguments after the script name need the <code>--</code> separator (<code>npm run vet -- &lt;mint&gt;</code>).</p><h2 id="trading-loop" tabindex="-1">Trading loop <a class="header-anchor" href="#trading-loop" aria-label="Permalink to &quot;Trading loop&quot;">​</a></h2><h3 id="npm-run-run" tabindex="-1"><code>npm run run</code> <a class="header-anchor" href="#npm-run-run" aria-label="Permalink to &quot;`npm run run`&quot;">​</a></h3><p>Starts the bot: the tick loop that scans, vets, enters, manages, and exits. Holds the single-instance lock (<code>data/farmer.lock</code>).</p><ul><li><strong>One instance per wallet/DB — ever.</strong> See <a href="./risk#one-instance-per-wallet">Risk &amp; sizing</a>, including the Windows gotcha where killing <code>npm</code> leaves the <code>tsx</code> child trading.</li><li>On a server, prefer PM2 (<code>meteora-farmer</code> app) so crashes auto-restart — see <a href="./advanced">Advanced setup</a>.</li><li>Restart-safe: on boot it reconciles the DB against the chain (chain wins) and resumes.</li></ul><h3 id="npm-run-status" tabindex="-1"><code>npm run status</code> <a class="header-anchor" href="#npm-run-status" aria-label="Permalink to &quot;`npm run status`&quot;">​</a></h3><p>The at-a-glance report, safe to run any time (read-only):</p><ul><li>Open positions table: id, symbol, entry SOL/price, state, claimed fees, opened time.</li><li>Closed totals: count, <strong>measured</strong> realized PnL in SOL, and how much of that was fee income.</li><li>The <strong>paper→live promotion scoreboard</strong>: consecutive profitable days vs the required 7, per-day realized and unrealized-delta lines, and <code>ELIGIBLE</code> when the gate is met.</li></ul><h2 id="stopping-things" tabindex="-1">Stopping things <a class="header-anchor" href="#stopping-things" aria-label="Permalink to &quot;Stopping things&quot;">​</a></h2><h3 id="npm-run-halt" tabindex="-1"><code>npm run halt</code> <a class="header-anchor" href="#npm-run-halt" aria-label="Permalink to &quot;`npm run halt`&quot;">​</a></h3><p>Toggles the <code>HALT</code> file. First run: the farmer closes <strong>all</strong> positions, swaps to SOL, and idles. Second run: clears HALT so the farmer resumes on the next tick. Same file the dashboard&#39;s red HALT button writes.</p><h3 id="npm-run-pause" tabindex="-1"><code>npm run pause</code> <a class="header-anchor" href="#npm-run-pause" aria-label="Permalink to &quot;`npm run pause`&quot;">​</a></h3><p>Toggles the <code>PAUSE</code> file — the soft pause. Trading engine OFF, <strong>positions stay open</strong> and watched; run again to turn back ON. Same file as the dashboard header ON/OFF toggle. Use this for &quot;stop making new decisions&quot;; use <code>halt</code> for &quot;get me out of everything&quot;.</p><h3 id="npm-run-blacklist-clear-key-key" tabindex="-1"><code>npm run blacklist [-- clear &lt;key&gt; [key…]]</code> <a class="header-anchor" href="#npm-run-blacklist-clear-key-key" aria-label="Permalink to &quot;`npm run blacklist [-- clear &lt;key&gt; [key…]]`&quot;">​</a></h3><p>Lists every blacklist entry (token mints and creator addresses, with expiry or <code>PERMANENT</code>), or lifts the ones you name. <strong>P0 can be wrong</strong> — a TVL drain on a thin pool looks like a rug — and until this existed there was no way to disagree with a ban short of editing the DB. Lifting a <strong>creator</strong> ban also resets that creator&#39;s rug count, because vetting fails <code>creator_rug_history</code> on any count above zero and would silently re-ban the creator on its next mint. The dashboard exposes the same thing at <code>GET /api/blacklist</code> and <code>POST /api/blacklist/clear</code> (re-enter the dash token, same bar as HALT).</p><h3 id="npm-run-force-close-id-reason" tabindex="-1"><code>npm run force-close -- &lt;id&gt; &quot;&lt;reason&gt;&quot;</code> <a class="header-anchor" href="#npm-run-force-close-id-reason" aria-label="Permalink to &quot;`npm run force-close -- &lt;id&gt; &quot;&lt;reason&gt;&quot;`&quot;">​</a></h3><p>Recovery tool for a DB row stuck <code>open</code> with <strong>nothing behind it on chain</strong> (the manager refuses to guess about such rows on its own). In live mode it checks the chain first and <strong>refuses</strong> if any tracked position account still exists — it cannot be used to write off a real position. The row&#39;s exit values are left NULL on purpose: the outcome is unknown, so it contributes 0 to realized PnL rather than a fabricated number. The command prints the exact undo SQL.</p><h3 id="npm-run-release-sol-note" tabindex="-1"><code>npm run release [-- &lt;sol&gt; [note]]</code> <a class="header-anchor" href="#npm-run-release-sol-note" aria-label="Permalink to &quot;`npm run release [-- &lt;sol&gt; [note]]`&quot;">​</a></h3><p>Returns <strong>banked</strong> SOL (skimmed by profit locks / the retired house-money rule) to the deployable bankroll, through the ledger with a note — not a hand-written DB poke. No argument (or <code>all</code>) releases everything banked; a number releases that much. Prints the before/after banked totals and the undo statement.</p><h2 id="research-diagnosis" tabindex="-1">Research &amp; diagnosis <a class="header-anchor" href="#research-diagnosis" aria-label="Permalink to &quot;Research &amp; diagnosis&quot;">​</a></h2><h3 id="npm-run-scan" tabindex="-1"><code>npm run scan</code> <a class="header-anchor" href="#npm-run-scan" aria-label="Permalink to &quot;`npm run scan`&quot;">​</a></h3><p>One scanner sweep, printed: how many pools were swept, the top candidates with score / fee-TVL / TVL / 30m volume / bin step / base fee / pool address — and when nothing passes (normal in quiet markets), the <strong>closest rejects</strong> with exactly which gate failed and by how much. The fastest way to sanity-check gate settings.</p><h3 id="npm-run-vet-mint" tabindex="-1"><code>npm run vet -- &lt;mint&gt;</code> <a class="header-anchor" href="#npm-run-vet-mint" aria-label="Permalink to &quot;`npm run vet -- &lt;mint&gt;`&quot;">​</a></h3><p>Runs the full vetting engine on a single token and prints the verdict, soft score /100, each hard failure with its value vs limit, and the raw facts JSON (authorities, holders, clusters, RugCheck, age). Use it to answer &quot;why won&#39;t the bot touch this token?&quot;</p><h3 id="npm-run-sim-options" tabindex="-1"><code>npm run sim -- [options]</code> <a class="header-anchor" href="#npm-run-sim-options" aria-label="Permalink to &quot;`npm run sim -- [options]`&quot;">​</a></h3><p>Replays closed positions against <strong>alternative exit settings</strong> — the backtest that answers &quot;would a different stop / grace / escape setting have made more SOL on the trades we actually took?&quot;</p><p>It reads <code>position_marks</code> (one row per 15s manager poll: price, position value, active bin, unclaimed fees) and re-runs the mark-derivable part of the P0–P5 ladder over them with your overrides.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sleeve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --age-max</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 120</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.stop_loss_frac=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.65</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sweep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.below_range_grace_min=5,10,15,25,40</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aggressive</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server=srv.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> railway=rw.db</span></span></code></pre></div><p><strong>Scenarios</strong>: <code>--set section.key=value</code> (repeatable), <code>--profile &lt;id|path&gt;</code> (a <a href="./profiles">profile</a> — exit keys only), <code>--sweep key=a,b,c</code> (one run per value). <strong>Cohort</strong>: <code>--sleeve</code>, <code>--age-max</code> / <code>--age-min</code> (token age at entry, in minutes), <code>--book</code>, <code>--since YYYY-MM-DD</code>, <code>--min-marks</code>, <code>--include-flagged</code>. <strong>Output</strong>: <code>--list</code> to see the cohort, <code>--top N</code> for per-position rows, <code>--json &lt;path&gt;</code> for the full result set. <strong>Post-exit audit</strong>: <code>--post-exit [min]</code> (default 60) answers &quot;did we cut this too early?&quot; — for each exit rule it reports the median high and low price reached after the exit as a multiple of what we sold at, how many rose 25%+ afterwards, how many got back to the entry price (where the whole range is traversed and the position would have converted fully to SOL), and how long the high took to arrive. Needs <code>npm run sim:backfill</code> first.</p><p>That audit is deliberately about <strong>price, not position value</strong>: valuing an LP position at a future price needs bin-by-bin liquidity and would swap a measurement for a model. Direction, extremes and &quot;did it come back to entry&quot; are enough to see whether an exit rule is systematically early.</p><p>Each scenario ends in a <strong>verdict</strong> — <code>IMPROVES</code>, <code>HURTS</code>, <code>NOISE</code>, or <code>NO-OP</code> — that a result has to earn. A delta only counts as real if it survives dropping its best two positions, fires on at least 8 positions, and points the same way on every book loaded. That is deliberate: the rule that scored +0.94 SOL in the 2026-08-20 young-launch research turned out to be one position with broken marks.</p><p>Two numbers to read before any delta:</p><ul><li><strong>Fidelity</strong> — how many real exits the replay reproduces from the current config. Below ~85% usually means the exit rules changed since those positions closed (it replays <em>today&#39;s</em> ladder); re-run with <code>--since &lt;date of the change&gt;</code>.</li><li><strong>Cohort</strong> — how many traces were dropped as unusable, and how many were kept despite exiting by a rule the replay cannot reproduce.</li></ul><p><strong>What it cannot answer.</strong> Marks written before v0.19.1 carry no TVL, pool fee rate or volume, so P0 <code>tvl_drain</code> / <code>pool_dead</code> / <code>rugcheck_flip</code> and P2 fee-volume decay are not simulated — the run reports how much of the cohort now records pool health, and those exit paths become replayable once enough of the book does. Neither are entry gates, vetting or sizing — there is no data for trades the bot never took, so a profile comparison here is about <strong>exit behaviour only</strong>. And because a position&#39;s marks stop at its real exit, the replay can evaluate exiting <em>earlier</em> far better than exiting <em>later</em>.</p><h3 id="npm-run-sim-backfill-options" tabindex="-1"><code>npm run sim:backfill -- [options]</code> <a class="header-anchor" href="#npm-run-sim-backfill-options" aria-label="Permalink to &quot;`npm run sim:backfill -- [options]`&quot;">​</a></h3><p>Fetches the <strong>price path after each closed position</strong> from GeckoTerminal (keyless, rate-limited) into the local DB, so the backtester can judge holding <em>longer</em> — not just cutting earlier. A position&#39;s own marks stop the moment it closes, which is why this exists.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sim:backfill</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # fill everything pending</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sim:backfill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # a chunk at a time</span></span></code></pre></div><p><code>--db &lt;path&gt;</code>, <code>--window &lt;min&gt;</code> (default 80, the cap for one API call), <code>--limit &lt;n&gt;</code> (default 200), <code>--pace &lt;ms&gt;</code> (default 2500), <code>--refetch</code>.</p><p>It is <strong>resumable and honest about gaps</strong>. Every position attempted gets a row, so a re-run continues where the last stopped, and each ends in one of: <code>ok</code>, <code>too_recent</code> (the window has not elapsed yet — retried on a later run), <code>no_bars</code>, <code>no_overlap</code>, <code>miscalibrated</code>, or <code>error</code>.</p><p><strong>Calibration is the point.</strong> GeckoTerminal is not our price feed, so each fetch also covers the 20 minutes <em>before</em> the exit, where we have our own recorded marks, and stores the ratio between the two series. A ratio near 1.0 means the same convention; a tight non-unit ratio is applied as a scale factor; a noisy one marks the position <code>miscalibrated</code> and its bars are stored but never used. An external price series is never averaged into a conclusion without first proving it tracks what we measured ourselves.</p><p>Then read it back with the audit below.</p><h3 id="npm-run-heartbeat-check" tabindex="-1"><code>npm run heartbeat-check</code> <a class="header-anchor" href="#npm-run-heartbeat-check" aria-label="Permalink to &quot;`npm run heartbeat-check`&quot;">​</a></h3><p>Runs the out-of-process liveness checker once by hand (normally it lives in cron). Exit codes: <code>0</code> healthy, <code>1</code> heartbeat stale/missing (alert sent), <code>2</code> the checker itself couldn&#39;t read the DB — which deliberately does <strong>not</strong> alert, so a broken checker can&#39;t page you about itself.</p><h2 id="dashboard-docs" tabindex="-1">Dashboard &amp; docs <a class="header-anchor" href="#dashboard-docs" aria-label="Permalink to &quot;Dashboard &amp; docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>npm run dash</code></td><td>Start the ops dashboard server (port 8787, needs <code>DASH_TOKEN</code>)</td></tr><tr><td><code>npm run dash:build</code></td><td>Build the React dashboard bundle (run once before first <code>dash</code>, or after UI updates)</td></tr><tr><td><code>npm run docs:dev</code></td><td>Local VitePress docs dev server</td></tr><tr><td><code>npm run docs:build</code></td><td>Build these docs into <code>docs/setup/</code></td></tr></tbody></table><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>npm run typecheck</code></td><td><code>tsc --noEmit</code> — the CI gate; the server only deploys typecheck-passing commits</td></tr><tr><td><code>npm test</code></td><td>Full vitest run with enforced coverage thresholds</td></tr><tr><td><code>npm run test:watch</code></td><td>Watch mode</td></tr></tbody></table><p class="cta-row"><a class="doc-btn ghost" href="./risk">Risk &amp; sizing</a><a class="doc-btn ghost" href="./advanced">Advanced setup</a><a class="doc-btn ghost" href="./dashboard">Dashboard</a><a class="doc-btn ghost" href="./faq">FAQ</a></p>',49)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
